/** Forge 1.20.1 stage 2 boundary. No external mod allowlist, no private code copying, no armor/autonomy. */
public final class ForgeAssimilation {
    private ForgeAssimilation() {}
    private static void thread(MinecraftServer s){if(!s.isSameThread())throw new IllegalStateException("Assimilation requires server main thread");}
    private static ServerPlayer player(MinecraftServer s,UUID id){thread(s);var p=s.getPlayerList().getPlayer(id);if(p==null||!p.isAlive())throw new IllegalStateException("Owner offline/dead");return p;}
    public static final class Data extends SavedData {
        private AssimilationLedger ledger=new AssimilationLedger(this::setDirty);private String loadError="";
        AssimilationLedger checked(){if(!loadError.isEmpty())throw new IllegalStateException("Assimilation SavedData invalid; refusing empty reset: "+loadError);return ledger;}
        public static Data load(CompoundTag tag){var d=new Data();try{if(tag.getInt("format")!=1)throw new IllegalArgumentException("Unknown SavedData format");var parts=tag.getList("ledger",Tag.TAG_STRING);var text=new StringBuilder();for(var p:parts){text.append(p.getAsString());if(text.length()>16_777_216)throw new IllegalArgumentException("Ledger quota");}if(text.length()==0)throw new IllegalArgumentException("Missing ledger");d.ledger=AssimilationLedger.load(SafeData.object(text.toString(),50_331_648,2_000_000),d::setDirty);}catch(RuntimeException invalid){d.loadError=invalid.getClass().getSimpleName()+": "+invalid.getMessage();}return d;}
        @Override public CompoundTag save(CompoundTag tag){String text=checked().save().toString();var parts=new ListTag();for(int i=0;i<text.length();i+=12000)parts.add(StringTag.valueOf(text.substring(i,Math.min(text.length(),i+12000))));tag.put("ledger",parts);tag.putInt("format",1);return tag;}
    }
    private static AssimilationLedger ledger(MinecraftServer s){thread(s);return s.overworld().getDataStorage().computeIfAbsent(Data::load,()->{if(java.nio.file.Files.exists(s.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data/nanites_assimilation.dat")))throw new IllegalStateException("Existing assimilation SavedData unreadable; refusing empty replacement");return new Data();},"nanites_assimilation").checked();}
    /** Sorted compound keys; preserve lists and tag types, including ForgeCaps and original complete item NBT. */
    static String canonical(Tag tag){if(tag instanceof CompoundTag c){var parts=new ArrayList<String>();for(String k:c.getAllKeys().stream().sorted().toList())parts.add(StringTag.valueOf(k)+":"+canonical(c.get(k)));return "{"+String.join(",",parts)+"}";}if(tag instanceof ListTag l){var parts=new ArrayList<String>();for(var e:l)parts.add(canonical(e));return "["+String.join(",",parts)+"]";}return tag.toString();}
    public static String identity(ItemStack stack){if(stack.isEmpty())throw new IllegalArgumentException("Empty stack");var one=stack.copy();one.setCount(1);return hash(canonical(one.save(new CompoundTag())));}
    private static String hash(String text){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}catch(Exception impossible){throw new IllegalStateException(impossible);}}
    private static JsonObject provenance(MinecraftServer s,UUID owner,String namespace,String origin){var p=new JsonObject();p.addProperty("owner",owner.toString());p.addProperty("world_tick",s.overworld().getGameTime());var player=s.getPlayerList().getPlayer(owner);if(player!=null)p.addProperty("dimension",player.level().dimension().location().toString());p.addProperty("origin",origin);p.addProperty("minecraft","1.20.1");p.addProperty("nanites",version("nanites"));p.addProperty("forge",version("forge"));p.addProperty("mod",namespace);p.addProperty("mod_version",version(namespace));p.addProperty("observation_version",1);return p;}
    private static String version(String mod){return ModList.get().getModContainerById(mod).map(c->c.getModInfo().getVersion().toString()).orElse("unavailable");}
    private static JsonArray tags(ItemStack stack){var a=new JsonArray();stack.getTags().map(t->t.location().toString()).sorted().forEach(a::add);return a;}
    private static void evidence(JsonObject traits,JsonArray evidence,String name,JsonElement value,String source){traits.add(name,value);var e=new JsonObject();e.addProperty("trait",name);e.addProperty("source",source);e.add("value",value.deepCopy());evidence.add(e);}
    private static void fact(JsonObject traits,JsonArray evidence,String name,Number value,String source){evidence(traits,evidence,name,new JsonPrimitive(value),source);}
    private static JsonObject profile(ItemStack stack){
        var p=new JsonObject();var traits=new JsonObject();var ev=new JsonArray();var observedTags=tags(stack);p.add("tags",observedTags);evidence(traits,ev,"tag_membership",observedTags,"ItemStack.getTags (registry tag membership, not physical composition)");
        fact(traits,ev,"max_stack",stack.getMaxStackSize(),"ItemStack.getMaxStackSize");fact(traits,ev,"max_damage",stack.getMaxDamage(),"ItemStack.getMaxDamage");fact(traits,ev,"damage",stack.getDamageValue(),"ItemStack.getDamageValue");
        fact(traits,ev,"fuel_ticks",ForgeHooks.getBurnTime(stack,RecipeType.SMELTING),"ForgeHooks.getBurnTime(SMELTING); not FE");
        var actions=new JsonArray();net.minecraftforge.common.ToolAction.getActions().stream().filter(stack::canPerformAction).map(a->a.name()).sorted().forEach(actions::add);evidence(traits,ev,"tool_actions",actions,"Item.getToolActions(stack)");
        if(stack.getItem() instanceof TieredItem t){var tier=t.getTier();fact(traits,ev,"tool_level",tier.getLevel(),"TieredItem.getTier.getLevel");fact(traits,ev,"tool_speed",tier.getSpeed(),"Tier.getSpeed; no universal block speed");fact(traits,ev,"tool_attack_bonus",tier.getAttackDamageBonus(),"Tier.getAttackDamageBonus");}
        if(stack.getItem() instanceof ArmorItem armor){fact(traits,ev,"armor_defense",armor.getDefense(),"ArmorItem.getDefense");fact(traits,ev,"armor_toughness",armor.getToughness(),"ArmorItem.getToughness");evidence(traits,ev,"armor_slot",new JsonPrimitive(armor.getEquipmentSlot().getName()),"ArmorItem.getEquipmentSlot");}
        var attributes=new JsonArray();for(var slot:EquipmentSlot.values())for(var entry:stack.getAttributeModifiers(slot).entries()){var attr=new JsonObject();attr.addProperty("slot",slot.getName());attr.addProperty("attribute",Objects.toString(ForgeRegistries.ATTRIBUTES.getKey(entry.getKey())));attr.addProperty("amount",entry.getValue().getAmount());attr.addProperty("operation",entry.getValue().getOperation().name());attributes.add(attr);}evidence(traits,ev,"equipment_attributes",attributes,"ItemStack.getAttributeModifiers for every EquipmentSlot; not applied to player");
        p.add("traits",traits);p.add("evidence",ev);p.addProperty("composition_semantics","Only item identity and observed tag classifications; chemical/secret properties unknown");if(p.toString().length()>8192)throw new IllegalArgumentException("Item observation exceeds 8KiB; cannot assimilate safely");return p;
    }
    private static AssimilationLedger.Sample sample(MinecraftServer s,UUID id,ItemStack stack,String origin){if(stack.isEmpty())return null;var key=ForgeRegistries.ITEMS.getKey(stack.getItem());var one=stack.copy();one.setCount(1);String payload=canonical(one.save(new CompoundTag()));return new AssimilationLedger.Sample(key.toString(),hash(payload),payload,stack.getCount(),profile(stack),provenance(s,id,key.getNamespace(),origin),Math.max(1,Math.min(64,stack.getMaxStackSize())));}
    private static ItemStack decode(AssimilationLedger.Sample sample){try{var stack=ItemStack.of(TagParser.parseTag(sample.payload()));if(stack.isEmpty()||!ForgeRegistries.ITEMS.getKey(stack.getItem()).toString().equals(sample.item())||!identity(stack).equals(sample.key()))throw new IllegalArgumentException("Original item unavailable or serialized identity changed; stock retained");stack.setCount(sample.amount());return stack;}catch(com.mojang.brigadier.exceptions.CommandSyntaxException e){throw new IllegalArgumentException("Original NBT invalid; stock retained",e);}}
    private static AssimilationLedger.Inventory inventory(MinecraftServer s,UUID id){var inv=player(s,id).getInventory();return new AssimilationLedger.Inventory(){
        final Map<Integer,ItemStack> prepared=new HashMap<>();public int size(){return inv.items.size();}public AssimilationLedger.Sample get(int slot){return sample(s,id,inv.items.get(slot),"inventory:slot="+slot);}
        public void prepare(Map<Integer,AssimilationLedger.Sample> assignments){prepared.clear();for(var e:assignments.entrySet()){var item=e.getValue();var verified=decode(item.amount()==0?item.sized(1):item);if(item.amount()>Math.min(inv.getMaxStackSize(),verified.getMaxStackSize()))throw new IllegalArgumentException("Current stack limit changed; recover smaller amount; no debit");prepared.put(e.getKey(),item.amount()==0?ItemStack.EMPTY:verified);}}
        public void set(int slot,AssimilationLedger.Sample item){inv.items.set(slot,prepared.get(slot));inv.setChanged();}
    };}
    private static JsonObject inspectRow(MinecraftServer s,UUID id,ItemStack stack,int slot){var o=new JsonObject();if(stack.isEmpty())return o;var key=ForgeRegistries.ITEMS.getKey(stack.getItem());o.addProperty("item",key.toString());o.addProperty("identity",identity(stack));o.addProperty("amount",stack.getCount());if(slot>=0)o.addProperty("slot",slot);o.add("profile",profile(stack));o.add("provenance",provenance(s,id,key.getNamespace(),slot<0?"registry_default_stack":"inventory:slot="+slot));return o;}
    private static boolean match(ItemStack stack,String query){return ForgeRegistries.ITEMS.getKey(stack.getItem()).toString().contains(query)||stack.getTags().anyMatch(t->t.location().toString().contains(query));}
    private static JsonObject page(JsonArray entries,int total,int next,String semantics){var o=new JsonObject();o.add("entries",entries);o.addProperty("total_candidates",total);o.addProperty("next_offset",next);o.addProperty("complete",next>=total);o.addProperty("pagination",semantics);return o;}
    private static boolean append(JsonArray entries,JsonObject row){if(entries.toString().length()+row.toString().length()>12000)return false;entries.add(row);return true;}
    private static JsonObject inspect(MinecraftServer s,UUID id,JsonObject args){
        var p=player(s,id);boolean registry=args.get("registry").getAsBoolean();String q=args.get("query").getAsString();int offset=args.get("offset").getAsInt(),limit=args.get("limit").getAsInt();var keys=registry?ForgeRegistries.ITEMS.getKeys().stream().sorted().toList():List.<ResourceLocation>of();int total=registry?keys.size():p.getInventory().items.size(),cursor=Math.min(offset,total);var a=new JsonArray();int examined=0;
        while(cursor<total&&a.size()<limit&&examined++<128){int slot=cursor++;var stack=registry?new ItemStack(ForgeRegistries.ITEMS.getValue(keys.get(slot))):p.getInventory().items.get(slot);if(stack.isEmpty()||!match(stack,q))continue;JsonObject row;try{row=inspectRow(s,id,stack,registry?-1:slot);}catch(RuntimeException failure){row=new JsonObject();row.addProperty("item",ForgeRegistries.ITEMS.getKey(stack.getItem()).toString());row.addProperty("error",failure.getClass().getSimpleName()+": "+failure.getMessage());}if(!append(a,row)){cursor--;break;}}
        return page(a,total,cursor,"offset is candidate cursor, <=128 candidates/12Ki chars per page; registry sorted IDs, inventory slots; registry defaults are not owned resources");
    }
    /** Durable stock APIs: deposit takes ownership and consumes supplied real stack; no public mint tool. */
    public static String deposit(MinecraftServer s,UUID id,ItemStack owned,int amount,String origin){thread(s);if(owned.isEmpty()||amount<1||amount>owned.getCount())throw new IllegalArgumentException("Actual owned stack amount required");var sample=sample(s,id,owned,origin);decode(sample.sized(1));ledger(s).deposit(id,sample,amount);owned.shrink(amount);return sample.key();}
    public static ItemStack withdraw(MinecraftServer s,UUID id,String key,int amount){thread(s);decode(ledger(s).peek(id,key,amount));return decode(ledger(s).withdraw(id,key,amount));}
    /** Decode exact stock without withdrawing; repair compatibility is checked against this actual item. */
    public static ItemStack preview(MinecraftServer s,UUID id,String key,int amount){thread(s);return decode(ledger(s).peek(id,key,amount));}
    public static long available(MinecraftServer s,UUID id,String key){return ledger(s).available(id,key);}
    public static JsonObject traits(MinecraftServer s,UUID id,String key){return ledger(s).traits(id,key);}
    public static String reserve(MinecraftServer s,UUID id,String key,int amount,String purpose){return ledger(s).reserve(id,key,amount,purpose);}
    public static JsonObject reservations(MinecraftServer s,UUID id){return ledger(s).reservations(id);}
    public static void release(MinecraftServer s,UUID id,String token){ledger(s).release(id,token);}
    public static ItemStack commit(MinecraftServer s,UUID id,String token){thread(s);var stock=ledger(s);var decoded=decode(stock.reserved(id,token));stock.commit(id,token);return decoded;}
    public static JsonObject live(MinecraftServer s,UUID id){var o=ledger(s).live(id);o.addProperty("recipe_count",s.getRecipeManager().getRecipes().size());o.addProperty("status","OBSERVED_SERVER_MAIN");return o;}
    private static JsonObject recipe(MinecraftServer s,Recipe<?> recipe){var o=new JsonObject();o.addProperty("id",recipe.getId().toString());o.addProperty("type",Objects.toString(ForgeRegistries.RECIPE_TYPES.getKey(recipe.getType())));o.addProperty("serializer",Objects.toString(ForgeRegistries.RECIPE_SERIALIZERS.getKey(recipe.getSerializer())));o.addProperty("mod_version",version(recipe.getId().getNamespace()));var ingredients=new JsonArray();for(var in:recipe.getIngredients())ingredients.add(in.toJson());o.add("inputs",ingredients);var result=recipe.getResultItem(s.registryAccess());var output=new JsonObject();output.addProperty("item",result.isEmpty()?"minecraft:air":ForgeRegistries.ITEMS.getKey(result.getItem()).toString());output.addProperty("amount",result.getCount());if(!result.isEmpty()){output.add("tags",tags(result));String nbt=canonical(result.save(new CompoundTag()));output.addProperty("stack_snbt",nbt.length()>4096?nbt.substring(0,4096):nbt);output.addProperty("nbt_truncated",nbt.length()>4096);}o.add("output",output);o.addProperty("special",recipe.isSpecial());o.addProperty("group",recipe.getGroup());o.addProperty("semantics","Public Ingredient.toJson and getResultItem only; input counts/layout, conditions and private machine execution unknown unless specific public fields below; no block association proven");if(recipe instanceof ShapedRecipe shaped){o.addProperty("crafting_width",shaped.getWidth());o.addProperty("crafting_height",shaped.getHeight());}if(recipe instanceof AbstractCookingRecipe cooking){o.addProperty("cooking_ticks",cooking.getCookingTime());o.addProperty("experience",cooking.getExperience());}if(o.toString().length()>12000)throw new IllegalArgumentException("Recipe public metadata exceeds 12KiB");return o;}
    private static JsonObject recipes(MinecraftServer s,String query,String type,int offset,int limit){var candidates=s.getRecipeManager().getRecipes().stream().sorted(Comparator.comparing(r->r.getId().toString())).toList();int cursor=Math.min(offset,candidates.size()),examined=0;var a=new JsonArray();long deadline=System.nanoTime()+5_000_000;
        while(cursor<candidates.size()&&a.size()<limit&&examined++<128&&(examined==1||System.nanoTime()<deadline)){var r=candidates.get(cursor++);String t=Objects.toString(ForgeRegistries.RECIPE_TYPES.getKey(r.getType()));if(!type.isEmpty()&&!type.equals(t))continue;try{var meta=recipe(s,r);if(query.isEmpty()||r.getId().toString().contains(query)||meta.get("inputs").toString().contains(query)||meta.get("output").toString().contains(query)){if(!append(a,meta)){cursor--;break;}}}catch(RuntimeException fail){var e=new JsonObject();e.addProperty("id",r.getId().toString());e.addProperty("error",fail.getClass().getSimpleName()+": "+fail.getMessage());a.add(e);}}
        return page(a,candidates.size(),cursor,"sorted recipe IDs, cursor over ALL candidates; <=128 candidates/5ms/page (one recipe can exceed time); reload can change order; public metadata not machine mapping");
    }
    private static JsonObject technology(MinecraftServer s,UUID id,JsonObject a){var target=a.getAsJsonObject("target");if(!target.get("type").getAsString().equals("block"))throw new IllegalArgumentException("Technology requires loaded block target");var args=new JsonObject();args.add("target",target.deepCopy());args.addProperty("offset",0);args.addProperty("limit",1);var observation=ForgeMachines.execute(s,id,"machine_inspect",args);observation.remove("escrow");
        for(var side:observation.getAsJsonArray("sides")){var face=side.getAsJsonObject();if(face.has("inventory")){face.remove("inventory");face.addProperty("item_handler",true);}if(face.has("tanks")){face.remove("tanks");face.addProperty("fluid_handler",true);}}
        var p=player(s,id);String dim=target.get("dimension").getAsString();var loc=ResourceLocation.tryParse(dim.isEmpty()?p.level().dimension().location().toString():dim);ServerLevel level=s.getLevel(ResourceKey.create(Registries.DIMENSION,loc));BlockPos pos=new BlockPos(target.get("x").getAsInt(),target.get("y").getAsInt(),target.get("z").getAsInt());var state=level.getBlockState(pos);var key=ForgeRegistries.BLOCKS.getKey(state.getBlock());observation.addProperty("block",key.toString());var tags=new JsonArray();state.getTags().map(t->t.location().toString()).sorted().forEach(tags::add);observation.add("tags",tags);observation.add("provenance",provenance(s,id,key.getNamespace(),"block:"+loc+":"+pos.toShortString()));observation.addProperty("private_apis","Unknown/not exposed; sided capabilities and RecipeManager only, not universal reactor/crafting replication");observation.add("recipes",recipes(s,key.getNamespace()+":","",a.has("offset")?a.get("offset").getAsInt():0,a.has("limit")?a.get("limit").getAsInt():1));observation.addProperty("recipes_relation","Namespace query only; NOT proof of execution by this block");if(observation.toString().length()>14000){var ids=new JsonArray();for(var row:observation.getAsJsonObject("recipes").getAsJsonArray("entries")){var shortRow=new JsonObject();for(String field:List.of("id","type","error"))if(row.getAsJsonObject().has(field))shortRow.add(field,row.getAsJsonObject().get(field).deepCopy());ids.add(shortRow);}observation.getAsJsonObject("recipes").add("entries",ids);observation.addProperty("recipe_details_omitted",true);observation.addProperty("recipe_details_access","recipe_search for public ingredients/output");}if(observation.toString().length()>14000)throw new IllegalArgumentException("Technology state exceeds bounded observation; no registration");return observation;
    }
    /** Verify public APIs for every integration step before adapter publication; resources/throughput remain live at execution. */
    public static void validateTechnology(MinecraftServer s,UUID id,JsonObject a){
        player(s,id);MachineTools.validate("technology_assimilate",a);var blueprint=MachineAdapters.validate(a.get("source").getAsString());
        for(var element:blueprint.getAsJsonArray("steps")){var step=element.getAsJsonObject();String tool=step.get("tool").getAsString();var args=step.getAsJsonObject("args").deepCopy();
            if(tool.startsWith("transfer_")){String capability=tool.equals("transfer_items")?"slots":tool.equals("transfer_energy")?"energy":"tank_count";for(String end:List.of("from","to")){var inspect=new JsonObject();inspect.add("target",args.get(end).deepCopy());inspect.addProperty("offset",0);inspect.addProperty("limit",1);var observed=ForgeMachines.execute(s,id,"machine_inspect",inspect);boolean supported=false;for(var face:observed.getAsJsonArray("sides")){var row=face.getAsJsonObject();if(row.has(capability)){if(capability.equals("energy"))supported|=row.getAsJsonObject("energy").get(end.equals("from")?"can_extract":"can_receive").getAsBoolean();else supported|=row.get(capability).getAsInt()>0;}}if(!supported)throw new UnsupportedOperationException("Integration step "+tool+" "+end+" lacks exposed "+capability+" API on requested side");}}
            else if(tool.equals("machine_control")){args.addProperty("preview",true);ForgeMachines.execute(s,id,tool,args);}
            else if(tool.equals("machine_inspect"))ForgeMachines.execute(s,id,tool,args);
            else if(tool.equals("scan_machines")){var inspect=new JsonObject();inspect.add("target",args.get("target").deepCopy());inspect.addProperty("offset",0);inspect.addProperty("limit",1);ForgeMachines.execute(s,id,"machine_inspect",inspect);}
            if(step.has("when")){var when=step.getAsJsonObject("when");ForgeMachines.execute(s,id,"machine_inspect",when.getAsJsonObject("args"));}
        }
        // Also validate ledger quota/candidate before the stage1 adapter file changes.
        var record=technologyRecord(s,id,a,blueprint);ledger(s).validateTechnologyCandidate(id,hash(a.get("project").getAsString()+"/"+a.get("name").getAsString()),record);
    }
    private static JsonObject technologyRecord(MinecraftServer s,UUID id,JsonObject a,JsonObject blueprint){var o=new JsonObject();o.add("observation",technology(s,id,a));o.add("blueprint",blueprint);o.addProperty("project",a.get("project").getAsString());o.addProperty("name",a.get("name").getAsString());o.addProperty("integration","Validated operational stage1 capability recipe; no code cloning or guaranteed private manufacture");return o;}
    public static JsonObject execute(MinecraftServer s,UUID id,String tool,JsonObject a){player(s,id);MachineTools.validate(tool,a);var stock=ledger(s);return switch(tool){
        case "material_inspect" -> inspect(s,id,a);
        case "assimilate_material" -> {stock.consume(id,inventory(s,id),a.get("slot").getAsInt(),a.get("item").getAsString(),a.get("identity").getAsString(),a.get("amount").getAsInt());var o=stock.live(id);o.addProperty("status","CONSUMED_EXACT_SERVER_MAIN");o.addProperty("consumed",a.get("amount").getAsInt());o.addProperty("key",a.get("identity").getAsString());yield o;}
        case "material_stock" -> stock.stock(id,a.get("offset").getAsInt(),a.get("limit").getAsInt());
        case "recover_material" -> {String key=a.get("key").getAsString();int n=a.get("amount").getAsInt();decode(stock.peek(id,key,n));stock.recover(id,inventory(s,id),key,n);var o=stock.live(id);o.addProperty("status","RECOVERED_EXACT_SERVER_MAIN");o.addProperty("recovered",n);yield o;}
        case "recipe_search" -> recipes(s,a.get("query").getAsString(),a.get("type").getAsString(),a.get("offset").getAsInt(),a.get("limit").getAsInt());
        case "technology_scan" -> technology(s,id,a);
        case "technology_assimilate" -> {var blueprint=MachineAdapters.validate(a.get("source").getAsString());var o=new JsonObject();o.add("observation",technology(s,id,a));o.add("blueprint",blueprint);o.addProperty("project",a.get("project").getAsString());o.addProperty("name",a.get("name").getAsString());o.addProperty("integration","Validated operational stage1 capability recipe; no code cloning or guaranteed private manufacture");String key=hash(a.get("project").getAsString()+"/"+a.get("name").getAsString());stock.technology(id,key,o);var receipt=new JsonObject();receipt.addProperty("key",key);receipt.addProperty("project",a.get("project").getAsString());receipt.addProperty("name",a.get("name").getAsString());receipt.addProperty("blueprint_version",blueprint.get("version").getAsInt());receipt.addProperty("status","REGISTERED_SERVER_MAIN");receipt.addProperty("integration",o.get("integration").getAsString());yield receipt;}
        case "technology_list" -> stock.technologies(id,a.get("offset").getAsInt(),a.get("limit").getAsInt());
        default -> throw new IllegalArgumentException("Unknown assimilation operation");
    };}
}
